import shelve

def L1(s):
    return s.decode('latin-1')

def _t():
    d1 = {}
    s = shelve.Shelf(d1, protocol=2, writeback=False)
    s['key1'] = [1, 2, 3, 4]
    assert s['key1'] == [1, 2, 3, 4], ('assertEqual', s['key1'], [1, 2, 3, 4])
    assert len(s) == 1, ('assertEqual', len(s), 1)
    s.close()
    try:
        len(*(s,))
    except ValueError:
        pass
    try:
        s['key1']
    except ValueError:
        pass
    else:
        raise AssertionError('Closed shelf should not find a key')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

